                   internal class SpriteParams {        public string Name;        public Dictionary<string, TypeObject> Data = new Dictionary<string, TypeObject>();        public SpriteParams(string name) {            Name = name;        }        public void AddData(string key, TypeObject value) {            Data.Add(key, value);        }    } SceneManager.AllSprites.ForEach(s => {                    SpriteParams spriteParams = SpriteParamsManager.GetSpriteParams(s, paramsWhiteList);                    XElement xSprite = new XElement("SPRITE",                        new XAttribute("Name", s.Name),                        new XAttribute("Type", s.ComponentType),                        new XAttribute("Kind", s.ComponentKind)                    );                    XElement xParams = new XElement(                        "params",                         spriteParams.Data.Select(x =>                            new XElement("param", new XAttribute("key", x.Key),                            new XAttribute("val", ParseValueTostring(x.Value)),                            new XAttribute("type", x.Value.ValueType.Name)                        )                    ));                    xSprite.Add(spriteParams);                    xSprites.Add(xSprite);                });        public static SpriteParams GetSpriteParams(Sprite sprite, List<string> paramsWhiteList) {            //Console.WriteLine("-------------------------------SPRITE:{0}--------------------------------", s.Name);            var spriteData = new SpriteParams(sprite.Name);            Type controlType = sprite.GetType();            PropertyInfo[] properties = controlType.GetProperties(BindingFlags.Public | BindingFlags.Instance); // | BindingFlags.DeclaredOnly            foreach (PropertyInfo p in properties) {                if (!paramsWhiteList.Contains(p.Name)) continue;                //Console.WriteLine("Name:{0} Type:{1} P:{2}", "\t" + p.Name, p.PropertyType, p.GetValue(sprite));                var value = p.GetValue(sprite, null);                spriteData.AddData(p.Name, new TypeObject(value));            }            return spriteData;        }